#!/usr/bin/env bash
# start.sh — convenience launcher for the PSF Workbench desktop app.
#
# Just runs ./workbench-ui, which is the Electron launcher RUN_ONCE.sh
# generates. If you've never bootstrapped, this script tells you so.
#
# Why this exists separately from workbench-ui:
#   - start.sh is the conventional name people look for in a repo
#   - workbench-ui is auto-generated by RUN_ONCE.sh and tracks the
#     Electron binary path; treat it as build output, not source
#   - editing workbench-ui by hand will be overwritten next time
#     RUN_ONCE.sh runs; edit start.sh instead

set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LAUNCHER="$REPO_DIR/workbench-ui"

if [[ ! -x "$LAUNCHER" ]]; then
  cat >&2 <<EOF
[start] workbench-ui not found.

The Electron launcher hasn't been generated yet. Run the bootstrap
once to install Node, Electron, and the UI dependencies:

    cd "$REPO_DIR"
    ./RUN_ONCE.sh

Then re-run ./start.sh.
EOF
  exit 1
fi

exec "$LAUNCHER" "$@"
